","export class ComplaintService {
 constructor() {
 this.tableName = "x_1536901_road_saf_complaint";
 }

 async list(filters = {}) {
 try {
 const searchParams = new URLSearchParams(filters);
 searchParams.set('sysparm_display_value', 'all');
 searchParams.set('sysparm_limit', '50');
 searchParams.set('sysparm_order', '-sys_created_on');

 const response = await fetch(`/api/now/table/${this.tableName}?${searchParams.toString()}`, {
 method: "GET",
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 });

 if (!response.ok) {
 const errorData = await response.json().catch(() => ({}));
 throw new Error(errorData.error?.message || `Failed to fetch complaints: ${response.statusText}`);
 }

 const { result } = await response.json();
 return result ? result : [];
 } catch (error) {
 console.error('Error fetching complaints:', error);
 throw error;
 }
 }

 async create(data) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}`, {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify(data),
 });

 if (!response.ok) {
 const errorData = await response.json().catch(() => ({}));
 throw new Error(errorData.error?.message || `Failed to create complaint: ${response.statusText}`);
 }

 return response.json();
 } catch (error) {
 console.error('Error creating complaint:', error);
 throw error;
 }
 }

 async update(sysId, data) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
 method: "PATCH",
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify(data),
 });

 if (!response.ok) {
 const errorData = await response.json().catch(() => ({}));
 throw new Error(errorData.error?.message || `Failed to update complaint: ${response.statusText}`);
 }

 return response.json();
 } catch (error) {
 console.error('Error updating complaint:', error);
 throw error;
 }
 }

 async delete(sysId) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
 method: "DELETE",
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 });

 if (!response.ok) {
 const errorData = await response.json().catch(() => ({}));
 throw new Error(errorData.error?.message || `Failed to delete complaint: ${response.statusText}`);
 }

 return response.ok;
 } catch (error) {
 console.error('Error deleting complaint:', error);
 throw error;
 }
 }
