export default function ComplaintList({ complaints, service, loading, onRefresh }) {
 const handleStatusChange = async (complaint, newState) => {
 try {
 const sysId = typeof complaint.sys_id === 'object' ? 
 complaint.sys_id.value : complaint.sys_id;

 await service.update(sysId, { state: newState });
 onRefresh();
 } catch (error) {
 console.error('Failed to update complaint status:', error);
 }
 };

 const formatDate = (dateStr) => {
 if (!dateStr) return 'N/A';
 const date = typeof dateStr === 'object' ? dateStr.display_value : dateStr;
 return new Date(date).toLocaleDateString('en-US', {
 year: 'numeric',
 month: 'short',
 day: 'numeric',
 hour: '2-digit',
 minute: '2-digit'
 });
 };

 const getPriorityColor = (priority) => {
 const priorityValue = typeof priority === 'object' ? priority.value : priority;
 switch (priorityValue) {
 case 'critical': return '#dc3545';
 case 'high': return '#fd7e14';
 case 'medium': return '#ffc107';
 case 'low': return '#28a745';
 default: return '#6c757d';
 }
 };

 const getStateColor = (state) => {
 const stateValue = typeof state === 'object' ? state.value : state;
 switch (stateValue) {
 case 'new': return '#007bff';
 case 'assigned': return '#17a2b8';
 case 'in_progress': return '#ffc107';
 case 'resolved': return '#28a745';
 case 'closed': return '#6c757d';
 case 'cancelled': return '#dc3545';
 default: return '#6c757d';
 }
 };

 if (loading) {
 return <div className="loading">Loading complaints...</div>;
 }

 return (
 <div className="complaints-list">
 <div className="list-header">
 <h2>Road Safety Complaints</h2>
 <button onClick={onRefresh} className="refresh-btn">
 🔄 Refresh
 </button>
 </div>

 {complaints.length === 0 ? (
 <div className="empty-state">
 <h3>No complaints found</h3>
 <p>No road safety complaints have been submitted yet.</p>
 </div>
 ) : (
 <div className="complaints-grid">
 {complaints.map(complaint => {
 const complaintNumber = typeof complaint.complaint_number === 'object' ? 
 complaint.complaint_number.display_value : complaint.complaint_number;
 const shortDesc = typeof complaint.short_description === 'object' ? 
 complaint.short_description.display_value : complaint.short_description;
 const location = typeof complaint.location === 'object' ? 
 complaint.location.display_value : complaint.location;
 const complainantName = typeof complaint.complainant_name === 'object' ? 
 complaint.complainant_name.display_value : complaint.complainant_name;
 const priority = typeof complaint.priority === 'object' ? 
 complaint.priority.display_value : complaint.priority;
 const state = typeof complaint.state === 'object' ? 
 complaint.state.display_value : complaint.state;
 const stateValue = typeof complaint.state === 'object' ? 
 complaint.state.value : complaint.state;
 const complaintType = typeof complaint.complaint_type === 'object' ? 
 complaint.complaint_type.display_value : complaint.complaint_type;
 const incidentDate = typeof complaint.incident_date === 'object' ? 
 complaint.incident_date.display_value : complaint.incident_date;

 return (
 <div key={complaintNumber} className="complaint-card">
 <div className="card-header">
 <div className="complaint-id">{complaintNumber}</div>
 <div className="complaint-badges">
 <span 
 className="priority-badge"
 style={{ backgroundColor: getPriorityColor(complaint.priority) }}
 >
 {priority}
 </span>
 <span 
 className="state-badge"
 style={{ backgroundColor: getStateColor(complaint.state) }}
 >
 {state}
 </span>
 </div>
 </div>

 <div className="card-content">
 <h4 className="complaint-title">{shortDesc}</h4>
 <div className="complaint-details">
 <div className="detail-row">
 <strong>Type:</strong> {complaintType}
