 Close
 </button>
 )}
 </div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}","import React from 'react';
import './Dashboard.css';

export default function Dashboard({ complaints, loading, onTabChange }) {
 if (loading) {
 return <div className="loading">Loading dashboard data...</div>;
 }

 // Calculate statistics
 const totalComplaints = complaints.length;
 const newComplaints = complaints.filter(c => {
 const state = typeof c.state === 'object' ? c.state.value : c.state;
 return state === 'new';
 }).length;

 const resolvedComplaints = complaints.filter(c => {
 const state = typeof c.state === 'object' ? c.state.value : c.state;
 return state === 'resolved' || state === 'closed';
 }).length;

 const criticalComplaints = complaints.filter(c => {
 const priority = typeof c.priority === 'object' ? c.priority.value : c.priority;
 return priority === 'critical';
 }).length;

 // Get complaint types distribution
 const typeDistribution = complaints.reduce((acc, complaint) => {
 const type = typeof complaint.complaint_type === 'object' ? 
 complaint.complaint_type.display_value : complaint.complaint_type;
 acc[type] = (acc[type] || 0) + 1;
 return acc;
 }, {});

 // Get recent complaints (last 5)
 const recentComplaints = complaints.slice(0, 5);

 return (
 <div className="dashboard">
 <div className="dashboard-stats">
 <div className="stat-card total">
 <h3>Total Complaints</h3>
 <div className="stat-number">{totalComplaints}</div>
 </div>
 <div className="stat-card new">
 <h3>New Complaints</h3>
 <div className="stat-number">{newComplaints}</div>
 </div>
 <div className="stat-card resolved">
 <h3>Resolved</h3>
 <div className="stat-number">{resolvedComplaints}</div>
 </div>
 <div className="stat-card critical">
 <h3>Critical Priority</h3>
 <div className="stat-number">{criticalComplaints}</div>
 </div>
 </div>

 <div className="dashboard-content">
 <div className="dashboard-section">
 <h2>Quick Actions</h2>
 <div className="quick-actions">
 <button 
 className="action-btn primary"
 onClick={() => onTabChange('submit')}
 >
 🚨 Submit New Complaint
 </button>
 <button 
 className="action-btn secondary"
 onClick={() => onTabChange('complaints')}
 >
 📋 View All Complaints
 </button>
 </div>
 </div>

 <div className="dashboard-section">
 <h2>Complaint Types Overview</h2>
 <div className="type-distribution">
 {Object.entries(typeDistribution).map(([type, count]) => (
 <div key={type} className="type-item">
 <span className="type-name">{type || 'Not specified'}</span>
 <span className="type-count">{count}</span>
 </div>
 ))}
 </div>
 </div>

 <div className="dashboard-section">
 <h2>Recent Complaints</h2>
 <div className="recent-complaints">
 {recentComplaints.length === 0 ? (
 <p>No complaints found.</p>
 ) : (
 recentComplaints.map(complaint => {
 const shortDesc = typeof complaint.short_description === 'object' ? 
 complaint.short_description.display_value : complaint.short_description;
 const complaintNumber = typeof complaint.complaint_number === 'object' ? 
 complaint.complaint_number.display_value : complaint.complaint_number;
 const state = typeof complaint.state === 'object' ? 
 complaint.state.display_value : complaint.state;
 const priority = typeof complaint.priority === 'object' ? 
 complaint.priority.display_value : complaint.priority;

 return (
 <div key={complaintNumber} className="recent-complaint">
 <div className="complaint-header">
 <span className="complaint-number">{complaintNumber}</span>
 <span className={`priority ${priority?.toLowerCase()}`}>{priority}</span>
 </div>
 <div className="complaint-desc">{shortDesc}</div>
 <div className="complaint-state">Status: {state}</div>
 </div>
 );
 })
 )}
 </div>
 </div>
 </div>
 </div>
 );
}",".form-container {
