import { ComplaintService } from './services/ComplaintService.js';
import ComplaintForm from './components/ComplaintForm.jsx';
import ComplaintList from './components/ComplaintList.jsx';
import Dashboard from './components/Dashboard.jsx';
import './app.css';

export default function App() {
 const svc = useMemo(() => new ComplaintService(), []);
 const [complaints, setComplaints] = useState([]);
 const [activeTab, setActiveTab] = useState('dashboard');
 const [loading, setLoading] = useState(false);
 const [error, setError] = useState(null);

 const refreshComplaints = async () => {
 setLoading(true);
 setError(null);
 try {
 const data = await svc.list();
 setComplaints(data);
 } catch (err) {
 setError(err.message);
 console.error('Failed to load complaints:', err);
 } finally {
 setLoading(false);
 }
 };

 useEffect(() => {
 refreshComplaints();
 }, []);

 const handleComplaintSubmit = async () => {
 await refreshComplaints();
 setActiveTab('complaints'); // Switch to complaints tab after submission
 };

 return (
 <div className="road-safety-app">
 <header className="app-header">
 <h1>🚦 Road Safety Complaint Management System</h1>
 <p>Report road safety issues to traffic police and authorities</p>
 </header>

 <nav className="app-nav">
 <button 
 className={activeTab === 'dashboard' ? 'active' : ''}
 onClick={() => setActiveTab('dashboard')}
 >
 Dashboard
 </button>
 <button 
 className={activeTab === 'submit' ? 'active' : ''}
 onClick={() => setActiveTab('submit')}
 >
 Submit Complaint
 </button>
 <button 
 className={activeTab === 'complaints' ? 'active' : ''}
 onClick={() => setActiveTab('complaints')}
 >
 View Complaints
 </button>
 </nav>

 <main className="app-content">
 {error && (
 <div className="error-message">
 <strong>Error:</strong> {error}
 </div>
 )}

 {activeTab === 'dashboard' && (
 <Dashboard 
 complaints={complaints}
 loading={loading}
 onTabChange={setActiveTab}
 />
 )}

 {activeTab === 'submit' && (
 <ComplaintForm 
 service={svc} 
 onSubmit={handleComplaintSubmit}
 />
 )}

 {activeTab === 'complaints' && (
 <ComplaintList 
 complaints={complaints}
 service={svc}
 loading={loading}
 onRefresh={refreshComplaints}
 />
 )}
 </main>
 </div>
 );
